import{_ as u,a0 as r,w as p,s as m,ao as i,I as l,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"戴文的Linux內核專題：28 編譯與安裝 | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：28 編譯與安裝 | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：28 編譯與安裝 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：28 編譯與安裝 | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/28 The Linux Kernel--Compiling and Installing","title":"戴文的Linux內核專題：28 編譯與安裝","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/28 The Linux Kernel--Compiling and Installing.md","filePath":"[post].md"}'),s={name:"The Linux Kernel/28 The Linux Kernel--Compiling and Installing.md"};function d(g,t,x,q,T,C){const o=r("Link");return p(),m("div",null,[t[14]||(t[14]=i('<h1 id="戴文的linux內核專題-28-編譯與安裝" tabindex="-1">戴文的Linux內核專題：28 編譯與安裝 <a class="header-anchor" href="#戴文的linux內核專題-28-編譯與安裝" aria-label="Permalink to “戴文的Linux內核專題：28 編譯與安裝”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.762/.jpg" alt=""></p><p>你好！在花費了大量的時間在配置你需要的內核後，你現在可以編譯它了。源代碼是純文本形式的C代碼。這對人來可讀但是對機器可不是這樣。編譯會將代碼轉換成計算機可理解的一種稱之為二進制碼的形式(1是 [開]，0 是 [關])。編譯同樣會將所有內核代碼文件變成一個內核的文件。</p><p>為了編譯內核，在內核源代碼相同目錄下，在終端內輸入&quot;make&quot;。這會花費一些時間。完成之後，必須通過&quot;make modules&quot;來編譯模組。為了從一開始就簡化編譯過程，輸入&quot;make; make modules&quot;。這會先編譯接着是模組，而不用用户再回來輸入&quot;make modules&quot;。</p><p><img src="http://www.linux.org/attachments/compiling_01-png.763/.jpg" alt=""></p><p>警告：在你安裝一個內核時，備份所有的重要數據，確保有一份/boot目錄備份在FAT32的存儲卡上。這可以在如果安裝失敗後幫助修復系統。FAT32不會存儲權限，因此它更容易被用作live盤來還原數據。記住設置原始文件權限和可執行位。</p><p>一旦編譯已經成功完成，我們可以安裝內核到本地系統中(我會馬上解釋如何在其他系統上安裝內核[交叉編譯])。在相同的終端下，在編譯完成後，輸入&quot;make install&quot;。這會在/boot目錄下存放一些文件。&quot;vmlinuz&quot;(或者其他相似的名字)是內核自身。&quot;initrd&quot;是基於內存的文件系統，它被置於內存中且在啓動中使用。&quot;System-map&quot;包含了一張內核符號列表。這些全局變量和函數用於內核代碼。&quot;config&quot; 是內核的配置文件。grub.cfg會自動更新。然而，有些bootloder需要手動配置。內核安裝器會自動配置Grub，LILO和SysLinux bootloder。像BURG這類bootloder需要手動配置。模組的安裝同樣需要輸入&quot;make modules install&quot;。</p><p><img src="http://www.linux.org/attachments/compiling_04-png.764/.jpg" alt=""></p><p>注：內核和模組的安裝可以寫在一行-“make install &amp;&amp; make modules_install”。</p><p><img src="http://www.linux.org/attachments/compiling_05-png.765/.jpg" alt=""></p><p>一旦上面的過程完成了，用户可以通過重啓系統並在開機後在終端內輸入&quot;uname -r&quot;來確保內核已經安裝。如果系統無法啓動或者uname報告你預期外的版本號，這個問題可能眾多問題之一引起。或者是bootloader沒有正確設置，特性/配置衝突，編譯失敗，不正確的安裝，或者其他原因。找出問題源頭最好的方法是查看系統日誌(如果系統已經啓動到足以產生日誌)。&quot;dmsg&quot;是一個在屏幕上打印內核日誌的命令。查看錯誤、警告或者未預料的結果。如果系統沒有啓動或者沒有足夠啓動完全來生成日誌，使用live linux盤來執行診斷和修復。如果所有的都失敗了，再次編譯內核並確保你已經用root或者&quot;sudo&quot;安裝了內核。</p><p>注：最好的修復系統的方式是使用live Linux發行版來移除新的/損壞的內核，接着手動修復Grub文件(或者複製一個備份)。</p><p>一些Linux用户也喜歡安裝內核文檔，但這並不是必要。對於那些想要安裝文檔的用户，輸入這行，這裏的version是你的內核版本號 &quot;install -d /usr/share/doc/linux-VERSION &amp;&amp; cp -r Documentation/* /usr/share/doc/linux-VERSION&quot;(VERSION 是內核版本號)。很明顯，這需要root特權。</p><p>要是想編譯一個如你目前內核一樣特性的內核，輸入這條命令&quot;zcat /proc/config.gz &gt; .config&quot;。這個文件可能不存在，如果是這樣，你可能需要詢問你發行版/內核的開發者這個文件。&quot;zcat&quot;命令解壓並寫入數據到一個&quot;.config&quot;文件中。記住把&quot;.config&quot;放到合適的位置。這個文件應該放置在Linux內核目錄下，並允許它替換當前的文件。接着，像往常一樣編譯安裝你的內核即可。</p><p>交叉編譯稍微有點不同。為目標系統配置內核。確保內核配置完後，它是以交叉編譯配置的。當交叉編譯時，需要熟悉兩條術語。&quot;Host&quot;是執行編譯的系統，&quot;Target&quot;是接收新內核的系統。確保Host主機系統有合適的編譯器。比如，對於ARM系統的交叉編譯，用户需要在主機系統上有gcc-arm-linux-gnueabi。通常來説，開發者可以在他們的包管理器上搜尋或者Google到合適/最好的適合他們需要的交叉編譯器。比如用於ARM系統交叉編譯的命令是&quot;make ARCH=arm CROSS_COMPILE=arm-linux-gnueabi-&quot;。&quot;ARCH=arm&quot;指的是目標處理器的類型，&quot;CROSS_COMPILE&quot;指明瞭交叉編譯器。注意交叉編譯器前面缺少了&quot;gcc-&quot;並以連字符結束。這是用户在使用交叉編譯器作為參數使用時必須使用的格式。模組可以通過輸入&quot;make ARCH=arm CROSS_COMPILE=arm-linux-gnueabi- modules&quot;來交叉編譯。為了在目標系統上安裝內核，將內核文件夾複製到目標系統上。一旦文件已在目標系統上並在該目錄下打開了終端，輸入&quot;make install &amp;&amp; make modules_install&quot;。當然你必須是root或者使用&quot;sudo&quot;。</p>',15)),l("p",null,[t[1]||(t[1]=e("信息：Kernel.org放了一個支持的交叉編譯器列表(",-1)),a(o,{href:"https://www.kernel.org/pub/tools/crosstool/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.kernel.org/pub/tools/crosstool/",-1)])]),_:1}),t[2]||(t[2]=e(")。",-1))]),t[15]||(t[15]=i(`<h3 id="安裝編譯總結" tabindex="-1">安裝編譯總結: <a class="header-anchor" href="#安裝編譯總結" aria-label="Permalink to “安裝編譯總結:”">​</a></h3><h4 id="標準" tabindex="-1">標準: <a class="header-anchor" href="#標準" aria-label="Permalink to “標準:”">​</a></h4><pre><code>make &amp;&amp; make modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><h4 id="做一個更新的版本或者重整你的內核" tabindex="-1">做一個更新的版本或者重整你的內核: <a class="header-anchor" href="#做一個更新的版本或者重整你的內核" aria-label="Permalink to “做一個更新的版本或者重整你的內核:”">​</a></h4><pre><code>zcat /proc/config.gz &gt; .config &amp;&amp;  make &amp;&amp; make modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><h4 id="交叉編譯" tabindex="-1">交叉編譯: <a class="header-anchor" href="#交叉編譯" aria-label="Permalink to “交叉編譯:”">​</a></h4><pre><code>make ARCH={TARGET-ARCHITERCTURE} CROSS_COMPILE={COMPILER}; make ARCH={TARGET-ARCHITERCTURE} CROSS_COMPILE={COMPILER} modules &amp;&amp; make install &amp;&amp; make modules_install
</code></pre><p>下篇文章中，我們會討論加入和激活模組。謝謝！</p><hr>`,9)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),a(o,{href:"http://www.linux.org/threads/the-linux-kernel-compiling-and-installing.5208/"},{default:n(()=>[...t[3]||(t[3]=[e("http://www.linux.org/threads/the-linux-kernel-compiling-and-installing.5208/",-1)])]),_:1})]),l("p",null,[t[7]||(t[7]=e("譯者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[11]||(t[11]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),a(o,{href:"http://linux.cn/"},{default:n(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const f=u(s,[["render",d]]);export{L as __pageData,f as default};
